    const THOUGHT_KEYS = {
      bothNone: ['thought.both.none.1', 'thought.both.none.2'],
      bothGood: ['thought.both.good.1', 'thought.both.good.2'],
      water: {
        none: ['thought.water.none.1', 'thought.water.none.2'],
        low: ['thought.water.low.1', 'thought.water.low.2'],
        good: ['thought.water.good.1', 'thought.water.good.2'],
      },
      stand: {
        none: ['thought.stand.none.1', 'thought.stand.none.2'],
        low: ['thought.stand.low.1', 'thought.stand.low.2'],
        good: ['thought.stand.good.1', 'thought.stand.good.2'],
      },
    };

    const MEME_KEYS = [
      'meme.1',
      'meme.2',
      'meme.3',
      'meme.4',
      'meme.5',
      'meme.6',
      'meme.7',
      'meme.8',
      'meme.9',
    ];

    const THOUGHT_WEIGHT = { none: 3, low: 2, good: 1 };

    function thoughtTier(count, goodAt) {
      if (count <= 0) return 'none';
      return count >= goodAt ? 'good' : 'low';
    }

    function pickFromPool(pool, lastKey) {
      let index = Math.floor(Math.random() * pool.length);
      if (pool.length > 1 && pool[index] === lastKey) index = (index + 1) % pool.length;
      return pool[index];
    }

    function pickThoughtKey(water, stand, lastKey) {
      if (Math.random() < 0.35) return pickFromPool(MEME_KEYS, lastKey);
      const waterTier = thoughtTier(water, WATER_GOOD);
      const standTier = thoughtTier(stand, STAND_GOOD);
      if (waterTier === 'none' && standTier === 'none') {
        return pickFromPool(THOUGHT_KEYS.bothNone, lastKey);
      }
      if (waterTier === 'good' && standTier === 'good') {
        return pickFromPool(THOUGHT_KEYS.bothGood, lastKey);
      }
      const waterWeight = THOUGHT_WEIGHT[waterTier];
      const standWeight = THOUGHT_WEIGHT[standTier];
      const preferWater = Math.random() * (waterWeight + standWeight) < waterWeight;
      return preferWater
        ? pickFromPool(THOUGHT_KEYS.water[waterTier], lastKey)
        : pickFromPool(THOUGHT_KEYS.stand[standTier], lastKey);
    }

    const ROAST_KEYS = {
      generic: [
        'roast.1', 'roast.2', 'roast.3', 'roast.4', 'roast.5', 'roast.6',
        'roast.meme.1', 'roast.meme.2', 'roast.meme.3', 'roast.meme.4',
      ],
      waterNone: ['roast.waterNone'],
      standNone: ['roast.standNone'],
      bothGood: ['roast.bothGood'],
    };

    function pickRoastKey(water, stand, lastKey) {
      const pool = [...ROAST_KEYS.generic];
      if (water <= 0) pool.push(...ROAST_KEYS.waterNone);
      if (stand <= 0) pool.push(...ROAST_KEYS.standNone);
      if (water >= WATER_GOOD && stand >= STAND_GOOD) pool.push(...ROAST_KEYS.bothGood);
      return pickFromPool(pool, lastKey);
    }

    const PRAISE_KEYS = {
      water: ['praise.water.1', 'praise.water.2', 'praise.water.3', 'praise.water.4'],
      stand: ['praise.stand.1', 'praise.stand.2', 'praise.stand.3', 'praise.stand.4'],
    };

    function pickPraiseKey(kind, lastKey) {
      return pickFromPool(PRAISE_KEYS[kind] ?? PRAISE_KEYS.water, lastKey);
    }

    function synthesizeWaterSound(context, kind) {
      const now = context.currentTime + 0.02;
      const master = context.createGain();
      master.gain.setValueAtTime(0.0001, now);
      master.gain.exponentialRampToValueAtTime(0.6, now + 0.12);
      master.gain.setValueAtTime(0.6, now + 1.8);
      master.gain.exponentialRampToValueAtTime(0.0001, now + 2.65);
      master.connect(context.destination);

      const duration = 2.5;
      const buffer = context.createBuffer(1, Math.ceil(context.sampleRate * duration), context.sampleRate);
      const samples = buffer.getChannelData(0);
      for (let index = 0; index < samples.length; index += 1) {
        samples[index] = Math.random() * 2 - 1;
      }
      const noise = context.createBufferSource();
      noise.buffer = buffer;
      const band = context.createBiquadFilter();
      band.type = 'bandpass';
      band.Q.value = 0.75;
      band.frequency.setValueAtTime(780, now);
      band.frequency.linearRampToValueAtTime(1120, now + 2.1);
      const low = context.createBiquadFilter();
      low.type = 'lowpass';
      low.frequency.value = 2400;
      const noiseGain = context.createGain();
      noiseGain.gain.setValueAtTime(0.0001, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.14, now + 0.18);
      noiseGain.gain.setValueAtTime(0.14, now + 1.55);
      noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + 2.45);
      noise.connect(band).connect(low).connect(noiseGain).connect(master);

      const lfo = context.createOscillator();
      const lfoGain = context.createGain();
      lfo.frequency.value = 3.1;
      lfoGain.gain.value = 90;
      lfo.connect(lfoGain).connect(band.frequency);
      noise.start(now);
      noise.stop(now + duration);
      lfo.start(now);
      lfo.stop(now + duration);
      noise.onended = () => {
        noise.disconnect();
        band.disconnect();
        low.disconnect();
        noiseGain.disconnect();
        lfo.disconnect();
        lfoGain.disconnect();
      };

      const drops = kind === 'stand'
        ? [0.18, 0.62, 1.02, 1.48, 1.92]
        : [0.24, 0.76, 1.28, 1.8];
      for (const offset of drops) {
        const start = now + offset;
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        const base = 640 + Math.random() * 520;
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(base, start);
        oscillator.frequency.exponentialRampToValueAtTime(Math.max(170, base * 0.32), start + 0.18);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(0.06 + Math.random() * 0.02, start + 0.012);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.22);
        oscillator.connect(gain).connect(master);
        oscillator.start(start);
        oscillator.stop(start + 0.24);
        oscillator.onended = () => {
          oscillator.disconnect();
          gain.disconnect();
        };
      }

      window.setTimeout(() => {
        master.disconnect();
      }, 2800);
    }

    function playWaterSound(context, kind) {
      try {
        synthesizeWaterSound(context, kind);
      } catch (error) {
        console.warn('[fat-fish] water sound failed, using fallback chime', error);
        try {
          const now = context.currentTime + 0.02;
          const oscillator = context.createOscillator();
          const gain = context.createGain();
          oscillator.type = 'sine';
          oscillator.frequency.setValueAtTime(820, now);
          oscillator.frequency.exponentialRampToValueAtTime(520, now + 0.4);
          gain.gain.setValueAtTime(0.0001, now);
          gain.gain.exponentialRampToValueAtTime(0.08, now + 0.03);
          gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.7);
          oscillator.connect(gain).connect(context.destination);
          oscillator.start(now);
          oscillator.stop(now + 0.75);
        } catch {
          // Audio output is unavailable in this browser.
        }
      }
    }

    function synthesizeManboSound(context, kind) {
      // An original, copyright-safe "Manbo-style" jingle: no sampled audio and
      // no existing melody is reproduced.
      const now = context.currentTime + 0.02;
      const master = context.createGain();
      master.gain.setValueAtTime(0.0001, now);
      master.gain.exponentialRampToValueAtTime(0.7, now + 0.025);
      master.gain.setValueAtTime(0.7, now + 1.65);
      master.gain.exponentialRampToValueAtTime(0.0001, now + 2.4);
      master.connect(context.destination);

      const marimba = (start, frequency, level = 0.13, length = 0.22) => {
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        oscillator.type = 'triangle';
        oscillator.frequency.setValueAtTime(frequency * 1.015, start);
        oscillator.frequency.exponentialRampToValueAtTime(frequency, start + 0.025);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(level, start + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + length);
        oscillator.connect(gain).connect(master);
        oscillator.start(start);
        oscillator.stop(start + length + 0.02);
        oscillator.onended = () => {
          oscillator.disconnect();
          gain.disconnect();
        };
      };

      const bass = (start, frequency, level = 0.17) => {
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(frequency * 1.35, start);
        oscillator.frequency.exponentialRampToValueAtTime(frequency, start + 0.09);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(level, start + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.2);
        oscillator.connect(gain).connect(master);
        oscillator.start(start);
        oscillator.stop(start + 0.22);
        oscillator.onended = () => {
          oscillator.disconnect();
          gain.disconnect();
        };
      };

      const kick = (start, level = 0.26) => {
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(155, start);
        oscillator.frequency.exponentialRampToValueAtTime(52, start + 0.12);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(level, start + 0.008);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.16);
        oscillator.connect(gain).connect(master);
        oscillator.start(start);
        oscillator.stop(start + 0.18);
        oscillator.onended = () => {
          oscillator.disconnect();
          gain.disconnect();
        };
      };

      const noiseBuffer = context.createBuffer(1, Math.ceil(context.sampleRate * 0.06), context.sampleRate);
      const noiseSamples = noiseBuffer.getChannelData(0);
      for (let index = 0; index < noiseSamples.length; index += 1) {
        noiseSamples[index] = Math.random() * 2 - 1;
      }
      const shaker = (start, level = 0.035) => {
        const source = context.createBufferSource();
        source.buffer = noiseBuffer;
        const highpass = context.createBiquadFilter();
        highpass.type = 'highpass';
        highpass.frequency.value = 4800;
        const gain = context.createGain();
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(level, start + 0.005);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.055);
        source.connect(highpass).connect(gain).connect(master);
        source.start(start);
        source.stop(start + 0.07);
        source.onended = () => {
          source.disconnect();
          highpass.disconnect();
          gain.disconnect();
        };
      };

      const melody = [
        [0, 523.25],
        [0.18, 622.25],
        [0.36, 783.99],
        [0.54, 932.33],
        [0.78, 783.99],
        [0.96, 698.46],
        [1.14, 622.25],
        [1.32, 783.99],
        [1.56, 523.25],
      ];
      for (const [offset, frequency] of melody) {
        marimba(now + offset, frequency, offset === 1.56 ? 0.1 : 0.12, 0.2);
      }

      const beats = [0, 0.48, 0.96, 1.44];
      const bassNotes = [130.81, 196, 174.61, 196];
      for (let index = 0; index < beats.length; index += 1) {
        kick(now + beats[index]);
        bass(now + beats[index], bassNotes[index]);
      }
      for (const offset of [0.24, 0.72, 1.2, 1.68]) {
        shaker(now + offset);
      }

      marimba(now + 1.82, kind === 'stand' ? 1046.5 : 783.99, 0.08, 0.2);
      const boing = context.createOscillator();
      const boingGain = context.createGain();
      boing.type = 'sine';
      boing.frequency.setValueAtTime(180, now + 1.9);
      boing.frequency.exponentialRampToValueAtTime(640, now + 2.05);
      boingGain.gain.setValueAtTime(0.0001, now + 1.9);
      boingGain.gain.exponentialRampToValueAtTime(0.05, now + 1.92);
      boingGain.gain.exponentialRampToValueAtTime(0.0001, now + 2.18);
      boing.connect(boingGain).connect(master);
      boing.start(now + 1.9);
      boing.stop(now + 2.2);
      boing.onended = () => {
        boing.disconnect();
        boingGain.disconnect();
      };

      window.setTimeout(() => {
        master.disconnect();
      }, 2500);
    }

    function playManboSound(context, kind) {
      try {
        synthesizeManboSound(context, kind);
      } catch (error) {
        console.warn('[fat-fish] manbo sound failed, falling back to water', error);
        playWaterSound(context, kind);
      }
    }

