    function localDateKey(date) {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    }

    function sanitizeHistory(value) {
      if (value === null || typeof value !== 'object' || Array.isArray(value)) return {};
      const entries = [];
      for (const [key, record] of Object.entries(value)) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(key)) continue;
        const water = Math.max(0, Math.floor(Number(record?.water) || 0));
        const stand = Math.max(0, Math.floor(Number(record?.stand) || 0));
        if (water === 0 && stand === 0) continue;
        entries.push([key, { water, stand }]);
      }
      entries.sort((left, right) => left[0].localeCompare(right[0]));
      return Object.fromEntries(entries.slice(-120));
    }

    function addHistoryEntry(history, kind, date = new Date()) {
      const key = localDateKey(date);
      const previous = history[key] ?? { water: 0, stand: 0 };
      const next = {
        ...history,
        [key]: {
          water: previous.water + (kind === 'water' ? 1 : 0),
          stand: previous.stand + (kind === 'stand' ? 1 : 0),
        },
      };
      const keys = Object.keys(next).sort();
      if (keys.length > 120) {
        return Object.fromEntries(keys.slice(-120).map((day) => [day, next[day]]));
      }
      return next;
    }

